'use strict';
// Bank connection entry - provider-neutral, DOM-free helpers (no network, no storage, no markup). Nothing here knows any bank data provider:
// the only contract is  POST /api/bank/connect -> { authorizationUrl, state }  and  POST /api/bank/consent { code, state }.

/** sessionStorage key holding the consent state between leaving for the bank and coming back. */
const BANK_STATE_KEY = 'nordla.bank.state';

/** The bank's authorization page is only ever opened when it is a well-formed https URL (never javascript:, data:, http: or a relative path). */
function safeAuthorizationUrl(url) {
  try { const u = new URL(String(url)); return u.protocol === 'https:' && u.hostname ? u.href : null; } catch (e) { return null; }
}

/** What the connect window offers, from the real bank status: the automatic connection only exists when a provider is configured; the CSV import is always the working path. */
function bankConnectPlan(status) {
  const configured = !!(status && status.adapter && status.adapter.configured);
  return { automatic: configured, csvImport: !status || status.csvImportAvailable !== false, connected: !!(status && status.state === 'ACTIVE') };
}

/**
 * The bank sends the user back to Nordla with ?code&state (success) or ?error (refused / cancelled). Returns null when the URL is not a bank return.
 * Only fixed categories are returned - a provider's free text is never displayed.
 */
function parseBankReturn(search) {
  const p = new URLSearchParams(search || '');
  const code = p.get('code'); const state = p.get('state'); const error = p.get('error');
  if (!code && !state && !error) return null;
  if (error) return { kind: /access_denied|cancel|denied|declined/i.test(error) ? 'cancelled' : 'error' };
  if (!code || !state) return { kind: 'error' };
  return { kind: 'callback', code: code.slice(0, 500), state: state.slice(0, 200) };
}

/** The state we kept before leaving must be the state we got back; otherwise the return is refused and nothing is sent to the backend. */
function bankStateMatches(saved, got) { return typeof saved === 'string' && saved.length > 0 && saved === got; }


  // ---- src/finance/ui/civil-date.js ----
'use strict';
// The merchant's CIVIL date in the browser. DOM-free. The zone is the one the server reports (MERCHANT_TIMEZONE, in the settings payload);
// it is never the browser's own zone. Same rule as the server (src/finance/civil-date.js, which this mirrors with the same Intl call);
// test/finance-civil-date.test.js proves both give the same date across winter / summer / DST / the 00:00-02:00 window.

/** The merchant's calendar date (YYYY-MM-DD) for an instant. */
function civilDateIn(instant, timeZone) {
  const d = instant instanceof Date ? instant : new Date(instant);
  if (Number.isNaN(d.getTime())) throw new RangeError('civilDateIn: invalid instant');
  if (!timeZone) throw new TypeError('civilDateIn: a time zone is required');
  return new Intl.DateTimeFormat('en-CA', { timeZone, year: 'numeric', month: '2-digit', day: '2-digit' }).format(d);
}

/** Today in the merchant's zone (the form defaults and the period presets use this, never the browser's UTC or local day). */
function civilToday(timeZone) { return civilDateIn(new Date(), timeZone); }


  // ---- src/finance/ui/bank-csv.js ----
'use strict';
// Bank CSV statement import - DOM-free helpers (no network, no storage, no markup), shared by BOTH entry points: the file picker and
// the paste box. Both end in the same two backend calls - POST /api/bank/import-csv/preview (writes nothing), then, after the merchant
// confirms, POST /api/bank/import-csv (all-or-nothing). The file is read in the browser and only ever sent to this backend (never to an AI service).

/** The backend accepts a 4 MB JSON body; the CSV text itself must stay clearly under it. */
const CSV_MAX_BYTES = 3500000;
const CSV_ACCEPT = '.csv,text/csv';

/** A chosen file is only read when it looks like a CSV statement. Returns null (ok) or an error code. */
function csvFileProblem(file) {
  if (!file) return 'BANK_CSV_FILE_MISSING';
  const name = String(file.name || '').toLowerCase();
  const type = String(file.type || '').toLowerCase();
  const csvName = /\.csv$/.test(name);
  const csvType = type === 'text/csv' || type === 'application/csv' || type === 'application/vnd.ms-excel' || type === '';
  if (!csvName || !csvType) return 'BANK_CSV_FILE_TYPE';
  if (!file.size) return 'BANK_CSV_FILE_EMPTY';
  if (file.size > CSV_MAX_BYTES) return 'BANK_CSV_FILE_TOO_LARGE';
  return null;
}

/** Checks on the text itself (pasted, or read from the file as UTF-8) before anything is sent. */
function csvTextProblem(text) {
  const t = String(text || '');
  if (!t.trim()) return 'BANK_CSV_EMPTY';
  if (t.indexOf('\uFFFD') >= 0) return 'BANK_CSV_ENCODING_INVALID'; // not UTF-8: accents would be corrupted, so nothing is imported
  if (t.length > CSV_MAX_BYTES) return 'BANK_CSV_FILE_TOO_LARGE';
  return null;
}

/** A CSV line error as a message id (translated by the caller): it says which format is expected. */
const CSV_ROW_REASON = {
  DATE_INVALID: 'Invalid date (expected DD/MM/YYYY or YYYY-MM-DD)',
  AMOUNT_INVALID: 'Invalid amount (expected e.g. 12,50 or -1.234,56)',
};
function csvRowReason(reason) { return CSV_ROW_REASON[reason] || 'Invalid line'; }

/** What the preview allows: an import only when there is no invalid line and at least one new transaction. */
function csvImportPlan(preview) {
  if (!preview) return { canImport: false, count: 0, blocked: 'NO_PREVIEW' };
  const invalid = (preview.invalid || []).length;
  if (invalid) return { canImport: false, count: 0, blocked: 'ROWS_INVALID' };
  if (!preview.importable) return { canImport: false, count: 0, blocked: 'NOTHING_NEW' };
  return { canImport: true, count: preview.importable, blocked: null };
}


