const relationKey = (row) => (row.isCustomer && row.isSupplier ? 'both' : row.isCustomer ? 'customer' : row.isSupplier ? 'supplier' : 'none');
const relationText = (row) => tt(RELATION_TEXT[relationKey(row)]);
